export function storyFor(name){
 const main=name.split(/\+|증정/)[0];
 const kind=/손난로/.test(main)?'warmer':/헬로키티/.test(main)&&/고데기/.test(main)?'kitty':/바디.*드라이어/.test(main)?'dryer':livingProfile(main)?.id||'other';
 const person={warmer:'추위를 많이 타는 사람',kitty:'키티를 좋아하고 머리 손질을 자주 하는 사람',dryer:'욕실에서 쓸 가전을 찾는 사람'}[kind]||livingProfile(main)?.person||'물건의 쓰임과 취향을 함께 생각하는 사람';
 return {kind,person,...stories[kind]};
}
export function verifiedSentence(name,facts){
 const source=(name.split(/\+|증정/)[0]+'\n'+facts).split(/\n|[.!?]/).filter(s=>!/(\d[\d,.]*\s*(?:만\s*)?원|가격|할인|아닌|아니|없음|미지원|불가|별도|제외)/.test(s)).join(' ');
 if(/손난로/.test(name)&&/보조배터리/.test(source))return '손을 데우는 용도에 보조배터리 기능도 같이 쓸 수 있어.';
 if(/무선/.test(source)&&/파우치/.test(source))return '무선으로 쓰고 파우치에 넣어둘 수 있는 구성이라, 챙겨 다닐 물건을 찾을 때 같이 볼 만해.';
 const rules=[[/밝기\s*조절/,'밝기를 조절할 수 있어. 침대 옆에서 쓸지 책상에서 쓸지 생각하면서 골라보자.'],[/분리\s*세척/,'분리해서 세척할 수 있는 구조야. 매일 쓸 물건이라 관리하는 방법까지 같이 보게 돼.'],[/접이식/,'접어둘 수 있는 타입이야. 안 쓸 때 보관할 공간까지 생각하면 이런 부분도 중요하잖아.'],[/스테인리스|스텐레스/,'스테인리스로 되어 있어. 평소 이런 소재를 찾던 사람한테 보여주고 싶어.'],[/무선/,'무선으로 쓸 수 있어. 크기까지 확인해서 놓을 자리에 잘 맞는지 보려고 해.'],[/파우치\s*(?:포함|구성|세트)/,'파우치 포함 구성이야. 따로 보관할 것을 찾을 필요는 없겠어.']];
 return rules.find(([re])=>re.test(source))?.[1]||'';
}
